function waMissing(): array {$m=[];foreach(['WHATSAPP_ACCESS_TOKEN','WHATSAPP_PHONE_NUMBER_ID','WHATSAPP_APP_SECRET','WHATSAPP_VERIFY_TOKEN'] as $k)if(!env($k))$m[]=$k;if(env('WHATSAPP_PHONE_NUMBER_ID')&&!ctype_digit(env('WHATSAPP_PHONE_NUMBER_ID')))$m[]='WHATSAPP_PHONE_NUMBER_ID';if(!preg_match('/^v\d+\.0$/',env('WHATSAPP_API_VERSION','v25.0')))$m[]='WHATSAPP_API_VERSION';return $m;}
function waReady(): bool {return env('WHATSAPP_ENABLED')==='true'&&!waMissing();}
function waCall(string $endpoint,string $method='GET',mixed $body=null,bool $multipart=false): array {
    $headers=['Authorization: Bearer '.env('WHATSAPP_ACCESS_TOKEN')];if(!$multipart)$headers[]='Content-Type: application/json';$r=httpCall('https://graph.facebook.com/'.env('WHATSAPP_API_VERSION','v25.0').'/'.$endpoint,$method,$headers,$body===null?null:($multipart?$body:json_encode($body)));
    if($r['status']<200||$r['status']>=300)throw new HttpError('WhatsApp could not complete the request.',$r['status'],['providerCode'=>substr(preg_replace('/\D/','',(string)($r['json']['error']['code']??$r['status'])),0,12)]);return $r['json']??[];
}
function waAllowed(string $last): bool {$t=strtotime($last.' UTC');return $t!==false&&$t<=time()&&time()-$t<86400;}
function waConversation(int $id): array {$c=one('SELECT * FROM whatsapp_conversations WHERE id=? AND phone_number_id=?',[$id,env('WHATSAPP_PHONE_NUMBER_ID')]);if(!$c)fail('Conversation not found.',404);return $c;}
