            sql('INSERT INTO whatsapp_conversations(phone_number_id,customer_phone,customer_name,last_customer_at,last_message_at) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE customer_name=COALESCE(NULLIF(VALUES(customer_name),\'\'),customer_name)',[env('WHATSAPP_PHONE_NUMBER_ID'),$m['from'],$name,$date,$date]);$c=one('SELECT id FROM whatsapp_conversations WHERE phone_number_id=? AND customer_phone=? FOR UPDATE',[env('WHATSAPP_PHONE_NUMBER_ID'),$m['from']]);
            $media=in_array($m['type']??'',['image','document','audio','video','sticker'],true)?($m[$m['type']]??null):null;$body=textValue($m['text']['body']??$media['caption']??$m['button']['text']??$m['interactive']['button_reply']['title']??$m['interactive']['list_reply']['title']??($media?'':'['.clean($m['type']??'Unsupported',30).' message]'),4096);
