            sql("UPDATE whatsapp_messages m JOIN whatsapp_conversations c ON c.id=m.conversation_id SET m.provider_id=COALESCE(m.provider_id,?),m.status=CASE WHEN m.status='read' THEN 'read' WHEN m.status='delivered' AND ? IN ('sent','failed') THEN 'delivered' WHEN m.status='failed' AND ?='sent' THEN 'failed' ELSE ? END,m.error_code=CASE WHEN ?='failed' THEN ? ELSE m.error_code END WHERE c.phone_number_id=? AND c.customer_phone=? AND m.direction='outbound' AND (m.provider_id=? OR (m.request_id=? AND m.provider_id IS NULL))",[$s['id'],$s['status'],$s['status'],$s['status'],$s['status'],substr(preg_replace('/\D/','',(string)($s['errors'][0]['code']??'')),0,12)?:null,env('WHATSAPP_PHONE_NUMBER_ID'),$s['recipient_id']??'',$s['id'],$request]);
