    if(!$body&&!$info||$info&&mb_strlen($body)>1024)fail('Enter a message or attachment; captions allow up to 1,024 characters.');$hash=hash('sha256',$body.$bytes);$old=one('SELECT * FROM whatsapp_messages WHERE request_id=?',[$request]);if($old){if((int)$old['conversation_id']!==$id||$old['request_hash']!==$hash)fail('This request belongs to a different message.',409);return $old;}
