}
function waAttachment(int $id): never {
    if(!waReady())fail('WhatsApp is not connected.',503);$m=one('SELECT m.* FROM whatsapp_messages m JOIN whatsapp_conversations c ON c.id=m.conversation_id WHERE m.id=? AND c.phone_number_id=?',[$id,env('WHATSAPP_PHONE_NUMBER_ID')]);if(!$m||!ctype_digit((string)$m['media_id']))fail('Attachment not found.',404);
